void hmi_gfx_mgr02_driver_dcu_isr(void)
{
}

void hmi_tuner_present_handler(LSH_PRESN_HANDLER_STATUS_T * p_presen_hndl_status_SP)
{
   if(p_presen_hndl_status_SP->presentation_status == LSH_DEACTIVATED_STATUS)
   {
      hmi_gfx_mgr02_if_set_screen(p_presen_hndl_status_SP->logic_state_id, 0);
   }
   else
   {
      hmi_gfx_mgr02_if_set_screen(p_presen_hndl_status_SP->logic_state_id, 1);
   }
}

void hmi_src_present_handler(LSH_PRESN_HANDLER_STATUS_T *p_presen_hndl_status_SP)
{
   if(p_presen_hndl_status_SP->presentation_status == LSH_DEACTIVATED_STATUS)
   {
      hmi_gfx_mgr02_if_set_screen(p_presen_hndl_status_SP->logic_state_id, 0);
   }
   else
   {
      hmi_gfx_mgr02_if_set_screen(p_presen_hndl_status_SP->logic_state_id, 1);
   }
}

UINT8 hmi_src_event_handler(LSH_EVENT_HANDLER_STATUS_T *p_event_hndl_status_SP)
{
   return(LSH_STATUS_ABSORBED);
}
UINT8 hmi_tuner_event_handler(LSH_EVENT_HANDLER_STATUS_T *p_event_hndl_status_SP)
{
   return(LSH_STATUS_ABSORBED);
}

void hmi_src_focus_handler(LSH_FOCUS_HANDLER_STATUS_T  *p_focus_hndl_status_SP)
{
   if(p_focus_hndl_status_SP->focus_status & LSH_ANIM_COMPLETE_STATUS)
   {
   }
}
void hmi_tuner_focus_handler(LSH_FOCUS_HANDLER_STATUS_T  *p_focus_hndl_status_SP)
{
}

void hmi_welcome_focus_handler(LSH_FOCUS_HANDLER_STATUS_T  *p_focus_hndl_status_SP)
{
   if(p_focus_hndl_status_SP->focus_status & LSH_ANIM_COMPLETE_STATUS)
   {
   #ifdef EAGLE_OPENGL
	  LSH_ADD_STATE(GFX_SCR_TUNER, ANIM_MAX_ID);
   #endif
   }
}

/*============================================================================
** Function Name:    
** Visibility:       
** Description:      
** Invocation:       
** Inputs/Outputs:   
** Critical Section: 
** Created:          09-Aug-2012 by EMANOJ1
** Updated:          09-Aug-2012 by EMANOJ1
**==========================================================================*/
int main(int argc, char * argv[])
{
   MSG    msg;
   UINT32 fl_prev_count = GetTickCount();
   UINT32 fl_cur_count;
   static int l_test_scr=0;

   SetTimer(NULL, 0, 32, GTTimerProc);
   hmi_gfx_mgr02_if_KSColdInit();
   hmi_lsh_initialize(1);
   hmi_gfx_mgr02_if_start();
   hmi_gfx_anim_engine_init();
   
#ifdef EAGLE_OPENGL
   LSH_ADD_STATE(GFX_SCR_WELCOME_ANIMATION, GFX_STARTUP_ANIM);
#else
   LSH_ADD_STATE(GFX_SCR_PHONE_MAIN, 255);
   l_test_scr = -1;
#endif
  
   while(1)
   {
      if(kbhit())
      {
         switch(getch())
         {
            case  27:return(0);
			case 'a':
				LSH_REM_STATE(l_test_scr, 255);
				l_test_scr++;
				LSH_ADD_STATE(l_test_scr, 255);
				printf("screen %d added\n",l_test_scr);
				if(l_test_scr >= GFX_MGR02_NUM_OF_SCREENS)l_test_scr=-1;
				break;
         }
      }
      fl_cur_count = GetTickCount();
      if((fl_cur_count-fl_prev_count) >= 33)
      {
          fl_prev_count += 33;
		  hmi_gfx_anim_engine();
          hmi_gfx_mgr02_if_KSTimedTask();
		  hmi_gfx_anim_engine_tick();
      }
      if(GetMessage(&msg, NULL, 0, 0))
      {
        TranslateMessage(&msg);
        DispatchMessage(&msg);
      }
   }
}

